    LDI R16, 118
    ST R30, R16
    ADIW R30, 1
    LDI R16, 255
    ST R30, R16
    LDI R31, 0

; Blend coefficients (c1: 8 bytes, c2: 8 bytes at 0x5D20)
    LDI R30, 0x20
    LDI R31, 0x5D
    LDI R16, 16
    ST R30, R16
    ADIW R30, 1
    LDI R16, 10
    ST R30, R16
    ADIW R30, 1
    LDI R16, 7
    ST R30, R16
    ADIW R30, 1
    LDI R16, 6
    ST R30, R16
    ADIW R30, 1
    LDI R16, 5
    ST R30, R16
    ADIW R30, 1
    LDI R16, 4
    ST R30, R16
    ADIW R30, 1
    LDI R16, 4
    ST R30, R16
    ADIW R30, 1
    LDI R16, 3
    ST R30, R16
    ADIW R30, 1
    LDI R16, 0
    ST R30, R16
    ADIW R30, 1
    LDI R16, 6
    ST R30, R16
    ADIW R30, 1
    LDI R16, 9
    ST R30, R16
    ADIW R30, 1
    LDI R16, 10
    ST R30, R16
    ADIW R30, 1
    LDI R16, 11
    ST R30, R16
    ADIW R30, 1
    LDI R16, 12
    ST R30, R16
    ADIW R30, 1
    LDI R16, 12
    ST R30, R16
    ADIW R30, 1
    LDI R16, 13
    ST R30, R16
    ADIW R30, 1
    LDI R31, 0

main:
    ; Generate initial pseudo-Gaussian noise (step 8) into img buffer (0x0600)
    ; 784 bytes = 4 outer * 196 inner, using 16-bit Galois LFSR + 2-byte average
    LDI R26, 0x00      ; X = &img[0] (0x0600)
    LDI R27, 0x06
    LDI R24, 0xE1      ; 16-bit LFSR seed low byte (0xACE1)
    LDI R25, 0xAC      ; 16-bit LFSR seed high byte
    LDI R18, 0xB4      ; LFSR polynomial tap mask
    LDI R22, 4
gen_noise_outer:
    LDI R23, 196
gen_noise_inner:
    LSR R25
    ROR R24
    BRCC no_xor
    EOR R25, R18
no_xor:
    MOV R20, R24
    ADD R20, R25
    ROR R20            ; average two uniform bytes -> bell-shaped 0..255
    ST X, R20
    ADIW R26, 1
    DEC R23
    BRNE gen_noise_inner
    DEC R22
    BRNE gen_noise_outer

    ; Render Initial Step 8 (Pure Noise)
    LDI R16, 8
    STS 0x0070, R16    ; cur_step = 8
    RCALL render_vram

    ; Denoising Loop: t = 7 down to 0
    LDI R19, 7         ; R19 = current step t
diffusion_step_loop:
    STS 0x0070, R19    ; save step t

    ; ----------------------------------------------------------------
    ; Stage 1: Encoder - Compute 12 Hidden Activations
    ; h_k = ReLU( ((t_embed[t, k] << 4) + sum(w_enc[k, j] * img[j])) >> 5 )
    ; ----------------------------------------------------------------
    LDI R22, 0         ; k = 0
node_loop:
    ; Load t_embed[t, k] from 0x2EC0 + t * 12 + k
    LDS R16, 0x0070    ; R16 = t
    LDI R17, 12
    MUL R16, R17       ; R1:R0 = t * 12
    ADD R0, R22        ; + k
    LDI R30, 0xC0
    LDI R31, 0x2E
    ADD R30, R0
    ADC R31, R1
    LD R24, Z          ; R24 = t_embed[t, k] (signed 8-bit)
    LDI R25, 0
    SBRC R24, 7
    LDI R25, 255       ; sign extend

    ; Shift left 4: R25:R24 << 4
    LDI R18, 4
t_shl_loop:
    LSL R24
    ROL R25
    DEC R18
    BRNE t_shl_loop

    ; Base address for w_enc[k]: 0x0A00 + k * 784
    ; 784 = 256 * 3 + 16 (0x0310)
    LDI R16, 16
    MUL R22, R16       ; R1:R0 = k * 16
    MOV R20, R0
    MOV R21, R1
    LDI R16, 3
    MUL R22, R16       ; R1:R0 = k * 3
    ADD R21, R0        ; R21:R20 = k * 784
    LDI R30, 0x00
    LDI R31, 0x0A
    ADD R30, R20
    ADC R31, R21       ; Z = &w_enc[k, 0]

    ; X = &img[0] (0x0600)
    LDI R26, 0x00
    LDI R27, 0x06

    ; 784 MAC operations: 28 outer * 28 inner
    LDI R18, 28
enc_mac_outer:
    LDI R19, 28
enc_mac_inner:
    LD R16, Z          ; R16 = w_enc[k, j] (signed)
    LD R17, X          ; R17 = img[j] (unsigned)
    MULSU R16, R17     ; R1:R0 = w_enc * img (signed 16-bit)
    ADD R24, R0
    ADC R25, R1
    ADIW R30, 1
    ADIW R26, 1
    DEC R19
    BRNE enc_mac_inner
    DEC R18
    BRNE enc_mac_outer

    ; Shift right 5 arithmetic: (R25:R24) >> 5
    LDI R18, 5
enc_shr_loop:
    ASR R25
    ROR R24
    DEC R18
    BRNE enc_shr_loop

    ; ReLU: if sum < 0 then 0, clamp max 127
    SBRC R25, 7
    RJMP relu_zero
    CPI R25, 0
    BRNE relu_clamp_max
    CPI R24, 127
    BRCS relu_ok
relu_clamp_max:
    LDI R24, 127
    RJMP relu_ok
relu_zero:
    LDI R24, 0
relu_ok:
    ; Store into hidden[k] (at 0x0060 + k)
    LDI R30, 0x60
    LDI R31, 0x00
    ADD R30, R22
    ST R30, R24

    INC R22            ; k++
    CPI R22, 12
    BRNE node_loop

    ; Cache hidden activations into R2..R13 for high-throughput unrolled decoding
    LDS R2, 0x0060
    LDS R3, 0x0061
    LDS R4, 0x0062
    LDS R5, 0x0063
    LDS R6, 0x0064
    LDS R7, 0x0065
    LDS R8, 0x0066
    LDS R9, 0x0067
    LDS R10, 0x0068
    LDS R11, 0x0069
    LDS R12, 0x006A
    LDS R13, 0x006B

    ; ----------------------------------------------------------------
    ; Stage 2: Decoder & Blend - Reconstruct and Update img (784 pixels)
    ; Sequential pointers: Y=&b_dec, Z=&w_dec, X=&img
    ; ----------------------------------------------------------------
    LDS R19, 0x0070    ; restore t
    ; Load c1 from 0x5D20 + t, c2 from 0x5D28 + t
    LDI R30, 0x20
    LDI R31, 0x5D
    ADD R30, R19
    LD R14, Z          ; R14 = c1
    LDI R30, 0x28
    LDI R31, 0x5D
    ADD R30, R19
    LD R15, Z          ; R15 = c2

    ; Pointers for sequential pass:
    ; Y = &b_dec[0] (0x53E0)
    ; Z = &w_dec[0, 0] (0x2F20)
    ; X = &img[0] (0x0600)
    LDI R28, 0xE0
    LDI R29, 0x53
    LDI R30, 0x20
    LDI R31, 0x2F
    LDI R26, 0x00
    LDI R27, 0x06

    ; 784 pixels: 28 outer * 28 inner
    LDI R22, 28        ; outer loop counter
pixel_dec_outer:
    LDI R23, 28        ; inner loop counter
pixel_dec_inner:
    ; Load 16-bit b_dec from Y
    LD R24, Y
    ADIW R28, 1
    LD R25, Y
    ADIW R28, 1

    ; Unrolled 12-term MAC directly against cached hidden registers R2..R13
    LD R16, Z
    ADIW R30, 1
    MULS R16, R2
    ADD R24, R0
    ADC R25, R1

    LD R16, Z
    ADIW R30, 1
    MULS R16, R3
    ADD R24, R0
    ADC R25, R1

    LD R16, Z
    ADIW R30, 1
    MULS R16, R4
    ADD R24, R0
    ADC R25, R1

    LD R16, Z
    ADIW R30, 1
    MULS R16, R5
    ADD R24, R0
    ADC R25, R1

    LD R16, Z
    ADIW R30, 1
    MULS R16, R6
    ADD R24, R0
    ADC R25, R1

    LD R16, Z
    ADIW R30, 1
    MULS R16, R7
    ADD R24, R0
    ADC R25, R1

    LD R16, Z
    ADIW R30, 1
    MULS R16, R8
    ADD R24, R0
    ADC R25, R1

    LD R16, Z
    ADIW R30, 1
    MULS R16, R9
    ADD R24, R0
    ADC R25, R1

    LD R16, Z
    ADIW R30, 1
    MULS R16, R10
    ADD R24, R0
    ADC R25, R1

    LD R16, Z
    ADIW R30, 1
    MULS R16, R11
    ADD R24, R0
    ADC R25, R1

    LD R16, Z
    ADIW R30, 1
    MULS R16, R12
    ADD R24, R0
    ADC R25, R1

    LD R16, Z
    ADIW R30, 1
    MULS R16, R13
    ADD R24, R0
    ADC R25, R1

    ; Piecewise Linear Sigmoid: R25:R24 = (R25:R24) >> 2 + 128
    ASR R25
    ROR R24
    ASR R25
    ROR R24
    LDI R16, 128
    ADD R24, R16
    LDI R16, 0
    ADC R25, R16

    ; Clamp to [0, 255] in R16
    SBRS R25, 7        ; if negative sign bit set -> clamp to 0
    RJMP check_pos_clamp
    LDI R16, 0
    RJMP clamp_done
check_pos_clamp:
    CPI R25, 0
    BREQ clamp_ok
    LDI R16, 255       ; clamp high
    RJMP clamp_done
clamp_ok:
    MOV R16, R24       ; x0_hat[i] is in R16
clamp_done:

    ; Blend: res = (c1 * R16 + c2 * img[i]) / 16
    MUL R16, R14       ; c1 * x0_hat
    MOV R20, R0
    MOV R21, R1

    LD R16, X          ; R16 = old img[i]
    MUL R16, R15       ; c2 * img[i]
    ADD R20, R0
    ADC R21, R1

    ; Divide by 16: shift right 4
    LSR R21
    ROR R20
    LSR R21
    ROR R20
    LSR R21
    ROR R20
    LSR R21
    ROR R20

    ; Store into img[i] and advance X
    ST X, R20
    ADIW R26, 1

    DEC R23
    BRNE pixel_dec_inner
    DEC R22
    BRNE pixel_dec_outer

    ; Render current step to VRAM
    RCALL render_vram

    LDS R19, 0x0070    ; restore step t
    DEC R19
    CPI R19, 255       ; checks underflow below 0
    BREQ diffusion_done
    RJMP diffusion_step_loop

diffusion_done:
    ; Infinite halt display loop
halt_loop:
    RJMP halt_loop

; ==================================================================
; SUBROUTINE: render_vram
; 1:1 Direct copy of 28x28 img (0x0600) into 32x32 VRAM (0x0200)
; Center region: rows 2..29, cols 2..29
; Also writes Header row 0 and Footer row 31
; ==================================================================
render_vram:
    ; Clear Row 0
    LDI R30, 0x00
    LDI R31, 0x02
    LDI R16, 32        ; ' '
    LDI R18, 32
clr_hdr_loop:
    ST R30, R16
    ADIW R30, 1
    DEC R18
    BRNE clr_hdr_loop

    ; Write Header Text at 0x0201: 'DIFFUSION MNIST:8'
    LDI R30, 0x01
    LDI R31, 0x02
    LDI R16, 68 ; 'D'
    ST R30, R16
    ADIW R30, 1
    LDI R16, 73 ; 'I'
    ST R30, R16
    ADIW R30, 1
    LDI R16, 70 ; 'F'
    ST R30, R16
    ADIW R30, 1
    LDI R16, 70 ; 'F'
    ST R30, R16
    ADIW R30, 1
    LDI R16, 85 ; 'U'
    ST R30, R16
    ADIW R30, 1
    LDI R16, 83 ; 'S'
    ST R30, R16
    ADIW R30, 1
    LDI R16, 73 ; 'I'
    ST R30, R16
    ADIW R30, 1
    LDI R16, 79 ; 'O'
    ST R30, R16
    ADIW R30, 1
    LDI R16, 78 ; 'N'
    ST R30, R16
    ADIW R30, 1
    LDI R16, 32 ; ' '
    ST R30, R16
    ADIW R30, 1
    LDI R16, 77 ; 'M'
    ST R30, R16
    ADIW R30, 1
    LDI R16, 78 ; 'N'
    ST R30, R16
    ADIW R30, 1
    LDI R16, 73 ; 'I'
    ST R30, R16
    ADIW R30, 1
    LDI R16, 83 ; 'S'
    ST R30, R16
    ADIW R30, 1
    LDI R16, 84 ; 'T'
    ST R30, R16
    ADIW R30, 1
    LDI R16, 58 ; ':'
    ST R30, R16
    ADIW R30, 1
    LDI R16, 56 ; '8'
    ST R30, R16
    ADIW R30, 1

    ; Step indicator: 'STEP:[' t ']' at 0x0216
    LDI R30, 0x16
    LDI R31, 0x02
    LDI R16, 83 ; 'S'
    ST R30, R16
    ADIW R30, 1
    LDI R16, 84 ; 'T'
    ST R30, R16
    ADIW R30, 1
    LDI R16, 69 ; 'E'
    ST R30, R16
    ADIW R30, 1
    LDI R16, 80 ; 'P'
    ST R30, R16
    ADIW R30, 1
    LDI R16, 58 ; ':'
    ST R30, R16
    ADIW R30, 1
    LDI R16, 91 ; '['
    ST R30, R16
    ADIW R30, 1
    LDS R16, 0x0070    ; step t
    LDI R17, 48        ; '0'
    ADD R16, R17       ; ASCII digit
    ST R30, R16
    ADIW R30, 1
    LDI R16, 93 ; ']'
    ST R30, R16

    ; Direct 1:1 copy of 28x28 img into centered 28x28 VRAM (rows 2..29, cols 2..29)
    ; X = &img[0] (0x0600)
    LDI R26, 0x00
    LDI R27, 0x06
    LDI R22, 0         ; r = 0..27
render_r_loop:
    ; VRAM row = 2 + r, col = 2
    ; VRAM row start: 0x0200 + (r + 2) * 32 + 2
    LDI R16, 2
    ADD R16, R22       ; R16 = r + 2
    LDI R17, 32
    MUL R16, R17       ; R1:R0 = (r + 2) * 32
    LDI R30, 0x02      ; col offset 2
    LDI R31, 0x02      ; base 0x0200
    ADD R30, R0
    ADC R31, R1        ; Z = &VRAM[r + 2, 2]

    LDI R23, 28        ; 28 columns
render_c_loop:
    LD R16, X
    ST R30, R16
    ADIW R26, 1
    ADIW R30, 1
    DEC R23
    BRNE render_c_loop

    INC R22
    CPI R22, 28
    BRNE render_r_loop

    ; Clear Footer row 31 (0x05E0..0x05FF)
    LDI R30, 0xE0
    LDI R31, 0x05
    LDI R16, 32
    LDI R18, 32
clr_ftr_loop:
    ST R30, R16
    ADIW R30, 1
    DEC R18
    BRNE clr_ftr_loop

    RET

